import numpy as np
from collections import defaultdict

def analyze_structure(grid, name):
    g = np.array(grid)
    print(f"\n=== {name} ===")

    # Find all 3s grouped by row
    rows_with_3s = defaultdict(list)
    for r in range(g.shape[0]):
        cols = np.where(g[r] == 3)[0]
        if cols.size > 0:
            rows_with_3s[r] = list(cols)

    print("Rows with 3s:")
    for r in sorted(rows_with_3s.keys()):
        print(f"  Row {r}: {rows_with_3s[r]}")

    # Find non-3, non-0 values (centers)
    print("\nNon-3, non-0 values:")
    for r in range(g.shape[0]):
        for c in range(g.shape[1]):
            val = g[r, c]
            if val != 0 and val != 3:
                print(f"  ({r}, {c}): {val}")

# Analyze demo input
analyze_structure(G['Demo pair 1 input'], 'Demo pair 1 input')

import numpy as np

def apply_rules(grid):
    """Apply the puzzle transformation rules"""
    g = np.array(grid)
    h, w = g.shape

    # Initialize output as copy of input
    out = g.copy()

    # Find centers (non-3, non-0 values)
    centers = []
    for r in range(h):
        for c in range(w):
            val = g[r, c]
            if val != 0 and val != 3:
                centers.append((r, c, val))

    print(f"Found {len(centers)} centers")

    # Apply rule for each center:
    # 1. Fill entire row with center value except through 3-boundaries
    # 2. Fill entire column with center value except through 3-boundaries

    # Get all positions of 3s
    positions_3 = set()
    for r in range(h):
        for c in range(w):
            if g[r, c] == 3:
                positions_3.add((r, c))

    for r_center, c_center, center_val in centers:
        # Fill row r_center
        for c in range(w):
            if (r_center, c) not in positions_3 and g[r_center, c] == 0:
                out[r_center, c] = center_val

        # Fill column c_center
        for r in range(h):
            if (r, c_center) not in positions_3 and g[r, c_center] == 0:
                out[r, c_center] = center_val

    return out

