# Let me verify my understanding: 
# For each center (r_c, c_c, v), the influence extends:
# - Vertically along column c_c, stopped by any 3 in that column
# - Horizontally along row r_c, stopped by any 3 in that row
# - 3s themselves stay as 3s (highest priority)

def apply_rule_v2(grid):
    """Rule: centers cast rays vertically/horizontally until blocked by 3"""
    g = np.array(grid)
    h, w = g.shape

    # Create result starting with zeros
    out = np.zeros((h, w), dtype=int)

    # Get positions of all 3s
    pos_3 = set(np.argwhere(g == 3))

    # Find centers
    centers = []
    for r in range(h):
        for c in range(w):
            val = g[r, c]
            if val != 0 and val != 3:
                centers.append((r, c, val))

    # Apply each center's rays
    for cr, cc, val in centers:
        # Vertical ray up
        for r in range(cr - 1, -1, -1):
            if (r, cc) in pos_3:
                break  # Blocked
            if out[r, cc] == 0:  # Don't overwrite existing values (for now)
                out[r, cc] = val

        # Vertical ray down
        for r in range(cr + 1, h):
            if (r, cc) in pos_3:
                break
            if out[r, cc] == 0:
                out[r, cc] = val

        # Horizontal ray left
        for c in range(cc - 1, -1, -1):
            if (cr, c) in pos_3:
                break
            if out[cr, c] == 0:
                out[cr, c] = val

        # Horizontal ray right
        for c in range(cc + 1, w):
            if (cr, c) in pos_3:
                break
            if out[cr, c] == 0:
                out[cr, c] = val

    # Fill center itself
    for cr, cc, val in centers:
        out[cr, cc] = val

    return out

