# For each cell, find ALL values that would affect it via ray casting
def apply_rule_with_blocking(grid):
    g = np.array(grid)
    h, w = g.shape
    out = np.zeros((h, w), dtype=int)

    # Get all positions of 3s
    pos_3 = {(r, c) for r in range(h) for c in range(w) if g[r, c] == 3}

    def blocked_ray(start_r, start_c, dr, dc):
        """Check if ray from (start_r, start_c) in direction (dr,dc) is blocked by a 3"""
        rr, cc = start_r + dr, start_c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if (rr, cc) in pos_3:
                return True
            rr += dr
            cc += dc
        return False

    def fill_ray(start_r, start_c, dr, dc):
        """Fill cells in direction (dr,dc) starting from (start_r,start_c)"""
        rr, cc = start_r + dr, start_c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if (rr, cc) in pos_3:
                break  # Stop at 3
            out[rr, cc] = g[start_r, start_c]
            rr += dr
            cc += dc

    for cr, cc, val in centers:
        # Fill up
        fill_ray(cr, cc, -1, 0)
        # Fill down
        fill_ray(cr, cc, 1, 0)
        # Fill left
        fill_ray(cr, cc, 0, -1)
        # Fill right
        fill_ray(cr, cc, 0, 1)

    # Restore 3s
    for r in range(h):
        for c in range(w):
            if g[r, c] == 3:
                out[r, c] = 3

    return out

