import numpy as np

def apply_rule_simple(grid):
    """Simplest interpretation: 
    1. Fill entire column for each center's column
    2. Fill entire row for each center's row (but skip columns with 3s anywhere)
    3. Restore 3s
    """
    g = np.array(grid)
    h, w = g.shape

    out = np.zeros((h, w), dtype=int)

    # Columns with 3s anywhere - horizontal fill skips these
    cols_skip = set(c for c in range(w) if np.any(g[:, c] == 3))

    pos_3 = {(r, c) for r in range(h) for c in range(w) if g[r, c] == 3}

    centers = [(cr, cc, cv) for cr in range(h) for cc in range(w) 
               for cv in [g[cr, cc]] if cv != 0 and cv != 3]

    for cr, cc, val in centers:
        # Always fill vertical
        for r in range(h):
            out[r, cc] = val

        # Horizontal fill ONLY if this row has 3s AND skip cols with 3s
        if np.any(g[cr, :] == 3):
            for c in range(w):
                if c not in cols_skip:
                    out[cr, c] = val

    # Restore 3s
    for r in range(h):
        for c in range(w):
            if g[r, c] == 3:
                out[r, c] = 3

    return out

